import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        long[] a = new long[n], g = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        long base = 0;
        for (int i = 0; i < n; i++) {
            long b = nextLong();
            base -= a[i] * b;
            g[i] = Math.abs(a[i]) + a[i] * b;
        }
        long w = 0;
        for (int i = 0; i < k; i++) w += g[i];
        long best = w;
        for (int i = k; i < n; i++) {
            w += g[i] - g[i - k];
            best = Math.max(best, w);
        }
        System.out.println(base + best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := nextInt(), nextInt()
	a, g := make([]int, n), make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	base := 0
	for i := range a {
		b := nextInt()
		base -= a[i] * b
		g[i] = max(a[i], -a[i]) + a[i]*b
	}
	w := 0
	for i := 0; i < k; i++ {
		w += g[i]
	}
	best := w
	for i := k; i < n; i++ {
		w += g[i] - g[i-k]
		best = max(best, w)
	}
	fmt.Println(base + best)
}
